INSERT INTO `announcements` VALUES (1,NULL,'Relief Distribution Schedule','Ayuda distribution will be held every Wednesday and Friday, 8:00 AM - 4:00 PM, at your barangay hall. Please bring a valid ID.\nWhat to bring: Valid ID + Barangay Clearance (to receive the ayuda)\nNote from Barangay Staff: Please fall in line and make it organize','normal',NULL,NULL,1,'2026-08-31 11:01:28'),(2,1,'Extended Claiming Hours','Due to high demand, Poblacion Barangay 1-A will extend claiming hours until 6:00 PM this Friday.','high',NULL,NULL,1,'2026-08-31 11:01:28'),(3,1,'Distribution Schedule - Poblacion','Ayuda distribution will be held this Saturday at the Barangay Hall. Bring a valid ID and barangay clearance.\nWhat to bring: Valid ID + Barangay Clearance (to receive the ayuda)\nNote from Barangay Staff: fall in line','high',NULL,NULL,1,'2026-09-02 23:32:41'),(4,NULL,'Citywide Reminder','Please keep your registered contact number updated. For concerns, contact your Barangay Hall.','normal',NULL,NULL,1,'2026-09-02 23:32:41'),(5,5,'Agdao Distribution Details','Relief goods distribution on Friday, 9:00 AM at Agdao Covered Court.','normal',NULL,NULL,1,'2026-09-02 23:32:41'),(6,NULL,'Citywide Ayuda Reminder','Ayuda distribution schedule updates will be posted here. Always bring a valid ID and barangay clearance.','normal',NULL,NULL,1,'2026-09-03 00:11:54'),(7,1,'Poblacion 1-A Schedule','Food pack distribution this Saturday.','high',NULL,NULL,1,'2026-09-03 00:11:54'),(8,4,'Agdao Relief Goods','Relief goods ready for distribution on Friday.','normal',NULL,NULL,1,'2026-09-03 00:11:54'),(9,1,'Ayuda Distribution - Food Packs - Poblacion Barangay 1-A','Schedule: September 20, 2026 at 9:00 AM\nVenue: Poblacion Hall\nDetails: Bring valid ID + barangay clearance.\nRecipients: 3 member(s) - each receives 1 pack','normal',NULL,NULL,1,'2026-09-05 22:38:38'),(10,1,'Ayuda Distribution - Food Packs - Poblacion Barangay 1-A','Schedule: September 26, 2026 at 10 pm\nVenue: Poblacion Barangay 1-A Hall\nDetails: yaya\nRecipients: 3 member(s) - each receives 1 pack','normal',NULL,NULL,1,'2026-09-05 22:41:31'),(12,1,'Ayuda Distribution - Food Packs - Poblacion Barangay 1-A','Schedule: September 26, 2026 at 10 pm\nVenue: Poblacion Barangay 1-A Hall\nRecipients: 2 member(s) - each receives 1 pack','normal',NULL,NULL,1,'2026-09-05 22:51:04'),(18,40,'Emergency Update: Flood - Poblacion Barangay 9-A','Incident: Flood\nSeverity: HIGH\nLocation: purok 2\nPeople affected: 19\nHelp needed: Food & Water\nDetails: urgent\n\nCSWDO / District Admin has responded. Support is being dispatched to Poblacion Barangay 9-A. Please stay safe and follow instructions from your Barangay Staff.','high','emergency_response',7,1,'2026-09-06 14:00:06'),(21,1,'Emergency Update: Emergency - Poblacion Barangay 1-A','Incident: Emergency\nSeverity: MEDIUM\nScheduled response: September 9, 2026 at 7 pm\nResponse / support being dispatched: yes coming\n\nCSWDO / District Admin has responded. Support is being dispatched to Poblacion Barangay 1-A. Please stay safe and follow instructions from your Barangay Staff.','high','emergency_response',3,1,'2026-09-06 15:15:06'),(22,5,'Emergency Update: Flood - Ilang','Incident: Flood\nSeverity: HIGH\nLocation: purok 2\nPeople affected: 34\nScheduled response: September 9, 2026 at 7 pm\nResponse / support being dispatched: kjfiksjfkjf\n\nCSWDO / District Admin has responded. Support is being dispatched to Ilang. Please stay safe and follow instructions from your Barangay Staff.','high','emergency_response',10,1,'2026-09-07 15:55:24'),(23,31,'Ayuda Distribution - Hygiene Kit - Agdao Dacudao','Schedule: September 11, 2026 at 10 pm\nVenue: Barangay Hall\nDetails: be early\nRecipients: 20 member(s) - each receives 1 kit\nPosted to your Barangay Staff. Post this to beneficiaries to announce the schedule, venue and final list.','normal','distribution_schedule',9,1,'2026-09-08 11:17:45'),(24,NULL,'remind','yahyahyah','normal',NULL,NULL,1,'2026-09-08 11:24:51'),(26,1,'ay