  KEY `idx_bc_category` (`category`),
  CONSTRAINT `beneficiary_categories_ibfk_1` FOREIGN KEY (`beneficiary_id`) REFERENCES `beneficiaries` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9912 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
