--
-- Table structure for table `distribution_logs`
--

DROP TABLE IF EXISTS `distribution_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `distribution_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `beneficiary_id` int(11) DEFAULT NULL,
  `inventory_id` int(11) NOT NULL,
  `barangay_id` int(11) NOT NULL,
  `distributed_by` int(11) DEFAULT NULL,
  `assistance_type` enum('cash','food_pack','relief_goods','sponsored','other','hygiene') NOT NULL DEFAULT 'other',
  `quantity` int(11) NOT NULL DEFAULT 1,
  `amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `location` varchar(150) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `distributed_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `beneficiary_id` (`beneficiary_id`),
  KEY `inventory_id` (`inventory_id`),
  KEY `barangay_id` (`barangay_id`),
  KEY `distributed_by` (`distributed_by`),
  CONSTRAINT `distribution_logs_ibfk_1` FOREIGN KEY (`beneficiary_id`) REFERENCES `beneficiaries` (`id`) ON DELETE CASCADE,
  CONSTRAINT `distribution_logs_ibfk_2` FOREIGN KEY (`inventory_id`) REFERENCES `inventory` (`id`) ON DELETE CASCADE,
  CONSTRAINT `distribution_logs_ibfk_3` FOREIGN KEY (`barangay_id`) REFERENCES `barangays` (`id`),
  CONSTRAINT `distribution_logs_ibfk_4` FOREIGN KEY (`distributed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1516998 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

