--
-- Table structure for table `distribution_schedules`
--

DROP TABLE IF EXISTS `distribution_schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `distribution_schedules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(150) NOT NULL,
  `aid_type` varchar(30) DEFAULT NULL,
  `barangay_id` int(11) NOT NULL,
  `district_id` int(11) NOT NULL,
  `venue` varchar(150) DEFAULT NULL,
  `schedule_date` date DEFAULT NULL,
  `schedule_time` varchar(30) DEFAULT NULL,
  `what_to_bring` text DEFAULT NULL,
  `note` text DEFAULT NULL,
  `status` enum('draft','published','completed') NOT NULL DEFAULT 'draft',
  `published_by` int(11) DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `barangay_id` (`barangay_id`),
  KEY `district_id` (`district_id`),
  KEY `published_by` (`published_by`),
  KEY `created_by` (`created_by`),
  CONSTRAINT `distribution_schedules_ibfk_1` FOREIGN KEY (`barangay_id`) REFERENCES `barangays` (`id`) ON DELETE CASCADE,
  CONSTRAINT `distribution_schedules_ibfk_2` FOREIGN KEY (`district_id`) REFERENCES `districts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `distribution_schedules_ibfk_3` FOREIGN KEY (`published_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `distribution_schedules_ibfk_4` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=550 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

