--
-- Table structure for table `eligibility_lists`
--

DROP TABLE IF EXISTS `eligibility_lists`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `eligibility_lists` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(150) NOT NULL,
  `barangay_id` int(11) NOT NULL,
  `district_id` int(11) NOT NULL,
  `assistance_type` enum('cash','food_pack','relief_goods','sponsored','other','hygiene') NOT NULL DEFAULT 'other',
  `cash_fund_type` enum('general','emergency') DEFAULT NULL,
  `inventory_id` int(11) DEFAULT NULL,
  `status` enum('draft','confirmed','completed') NOT NULL DEFAULT 'draft',
  `created_by` int(11) DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `barangay_id` (`barangay_id`),
  KEY `district_id` (`district_id`),
  KEY `inventory_id` (`inventory_id`),
  KEY `created_by` (`created_by`),
  CONSTRAINT `eligibility_lists_ibfk_1` FOREIGN KEY (`barangay_id`) REFERENCES `barangays` (`id`) ON DELETE CASCADE,
  CONSTRAINT `eligibility_lists_ibfk_2` FOREIGN KEY (`district_id`) REFERENCES `districts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `eligibility_lists_ibfk_3` FOREIGN KEY (`inventory_id`) REFERENCES `inventory` (`id`) ON DELETE SET NULL,
  CONSTRAINT `eligibility_lists_ibfk_4` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=528 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

