--
-- Table structure for table `inventory`
--

DROP TABLE IF EXISTS `inventory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inventory` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `barangay_id` int(11) DEFAULT NULL,
  `item_name` varchar(100) NOT NULL,
  `quantity` decimal(12,2) NOT NULL DEFAULT 0.00,
  `unit` varchar(30) DEFAULT 'pack',
  `source` varchar(100) DEFAULT NULL,
  `source_details` text DEFAULT NULL,
  `assistance_type` enum('cash','food_pack','relief_goods','sponsored','other') NOT NULL DEFAULT 'other',
  `cash_fund_type` enum('general','emergency') DEFAULT NULL,
  `location` varchar(150) DEFAULT NULL,
  `low_stock_threshold` int(11) NOT NULL DEFAULT 20,
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `barangay_id` (`barangay_id`),
  CONSTRAINT `inventory_ibfk_1` FOREIGN KEY (`barangay_id`) REFERENCES `barangays` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=313 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

